function x = twinInitialState(twin)
%TWININITIALSTATE  Initial conditions for the 25-state system.
%
%   Initial conditions are not zero for every state. The haemodynamic
%   states start at their covariate-adjusted baselines, arterial CO2 at
%   its baseline, and the norepinephrine compartments at the steady state
%   generated by endogenous production. Initialising the vasopressor
%   compartment at zero would make the first exogenous dose act on a
%   physiologically empty system and overstate its apparent potency.

ix = twin.ix;
x  = zeros(ix.n, 1);

x(ix.TPR)   = twin.L4.BaseTPR;
x(ix.SV)    = twin.L4.BaseSV;
x(ix.HR)    = twin.L4.BaseHR;
x(ix.tdeSV) = twin.L4.BaseSV * twin.L4.LTDE_SV;
x(ix.tdeHR) = twin.L4.BaseHR * twin.L4.LTDE_HR;
x(ix.PaCO2) = twin.L3.PaCO2base;
x(ix.hBis)  = 0;

% endogenous norepinephrine at steady state
a1 = twin.nore.uEndo / (twin.nore.CL / twin.nore.V1);
x(ix.noreA1) = a1;
x(ix.noreA2) = a1 * (twin.nore.Q/twin.nore.V1) / (twin.nore.Q/twin.nore.V2);
end
